import { _decorator, Component } from 'cc';
import { ItemDB, ItemDef, EquipSlot } from './Items';
import { EventBus, GameEvents } from '../core/EventBus';
import { PlayerStats } from '../player/PlayerStats';
const { ccclass } = _decorator;

export interface InvSlot {
    itemId: string;
    count: number;
}

@ccclass('Inventory')
export class Inventory extends Component {
    public capacity = 30;
    public slots: InvSlot[] = [];
    public equipment: Partial<Record<EquipSlot, string>> = {};
    public stats: PlayerStats | null = null;

    addItem(itemId: string, count = 1): boolean {
        const def = ItemDB[itemId];
        if (!def) return false;
        if (def.stackable) {
            const existing = this.slots.find(s => s.itemId === itemId);
            if (existing) { existing.count += count; this.emit(); return true; }
        }
        if (this.slots.length >= this.capacity) return false;
        this.slots.push({ itemId, count });
        this.emit();
        EventBus.emit(GameEvents.ITEM_PICKED_UP, def, count);
        return true;
    }

    removeItem(itemId: string, count = 1): boolean {
        const idx = this.slots.findIndex(s => s.itemId === itemId);
        if (idx < 0) return false;
        this.slots[idx].count -= count;
        if (this.slots[idx].count <= 0) this.slots.splice(idx, 1);
        this.emit();
        return true;
    }

    hasItem(itemId: string, count = 1): boolean {
        const s = this.slots.find(s => s.itemId === itemId);
        return !!s && s.count >= count;
    }

    countItem(itemId: string): number {
        const s = this.slots.find(s => s.itemId === itemId);
        return s ? s.count : 0;
    }

    useConsumable(itemId: string): boolean {
        const def = ItemDB[itemId];
        if (!def || def.kind !== 'consumable' || !this.stats) return false;
        if (!this.hasItem(itemId)) return false;
        if (def.heal) this.stats.heal(def.heal);
        if (def.restoreMp) { this.stats.mp = Math.min(this.stats.maxMP + this.stats.bonusMP, this.stats.mp + def.restoreMp); }
        this.removeItem(itemId, 1);
        return true;
    }

    equip(itemId: string): boolean {
        const def = ItemDB[itemId];
        if (!def || def.kind !== 'equipment' || !def.slot) return false;
        if (!this.hasItem(itemId)) return false;
        const slot = def.slot;
        // swap
        const prev = this.equipment[slot];
        this.equipment[slot] = itemId;
        this.removeItem(itemId, 1);
        if (prev) this.addItem(prev, 1);
        this.recalcBonuses();
        EventBus.emit(GameEvents.EQUIPMENT_CHANGED, this.equipment);
        return true;
    }

    unequip(slot: EquipSlot): boolean {
        const itemId = this.equipment[slot];
        if (!itemId) return false;
        delete this.equipment[slot];
        this.addItem(itemId, 1);
        this.recalcBonuses();
        EventBus.emit(GameEvents.EQUIPMENT_CHANGED, this.equipment);
        return true;
    }

    recalcBonuses() {
        if (!this.stats) return;
        let atk = 0, def = 0, hp = 0, mp = 0;
        for (const slot of Object.keys(this.equipment) as EquipSlot[]) {
            const id = this.equipment[slot];
            if (!id) continue;
            const it = ItemDB[id];
            const s = it.stats;
            if (!s) continue;
            atk += s.attack ?? 0;
            def += s.defense ?? 0;
            hp += s.hp ?? 0;
            mp += s.mp ?? 0;
        }
        this.stats.bonusAttack = atk;
        this.stats.bonusDefense = def;
        const oldBHP = this.stats.bonusHP, oldBMP = this.stats.bonusMP;
        this.stats.bonusHP = hp;
        this.stats.bonusMP = mp;
        // Re-clamp current HP/MP
        this.stats.hp = Math.min(this.stats.maxHP + this.stats.bonusHP, this.stats.hp + (hp - oldBHP));
        this.stats.mp = Math.min(this.stats.maxMP + this.stats.bonusMP, this.stats.mp + (mp - oldBMP));
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this.stats);
    }

    private emit() {
        EventBus.emit(GameEvents.INVENTORY_CHANGED, this);
    }
}